namespace ghidra.app.util.sourcelanguage;




using ghidra.app.util.bin.format.elf;
using ghidra.app.util.bin.format.elf.info;
using ghidra.app.util.opinion;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * The Elf Rust {@link SourceLanguage} class
 */
public class ElfRustSourceLanguage : RustSourceLanguage {

	private static readonly Pattern ELF_COMMENT_REGEX = Pattern.compile("^rustc version .*$");

	/* @Override */
	public bool existsIn(Program program, TaskMonitor monitor)
    {
		if (!program.getExecutableFormat().equals(ElfLoader.ELF_NAME)) {
			return false;
		}

		// ELF binaries can contain a ".comment" section that records the toolchains that
		// produced the binary.  Search this first as its quick and easy. 
		ElfComment elfComments = ElfComment.fromProgram(program);
		if (elfComments != null) {
			foreach (string s in elfComments.getCommentStrings()) {
				if (ELF_COMMENT_REGEX.matcher(s).matches()) {
					return true;
				}
			}
		}

		foreach (MemoryBlock block in program.getMemory().getBlocks()) {
			if (block.getName().equals(ElfSectionHeaderConstants.dot_rodata) &&
				isRust(program, block, monitor)) {
				return true;
			}
		}
		return false;
	}
}
